package com.smarttrafficflow.backend.domain.analytics.service;

import java.util.List;
import java.util.Locale;

/**
 * Weather codes generated by the simulation and the name the screen shows for each one. The names are the same as
 * {@code weatherLabels} in the frontend (src/lib/labels.ts): the table search finds records by what the screen shows.
 */
public final class WeatherTypes {

    private static final List<String> CODES = List.of("SUNNY", "RAIN", "CLOUDY");

    private WeatherTypes() {
    }

    /**
     * Name of the weather for a person reading a text. Like the screen, it accepts a code in any case. Weather typed
     * by a person is free text and is shown as it was registered.
     */
    public static String label(String weather) {
        return switch (weather.toUpperCase(Locale.ROOT)) {
            case "SUNNY" -> "Ensolarado";
            case "RAIN" -> "Chuva";
            case "CLOUDY" -> "Nublado";
            default -> weather;
        };
    }

    /** The codes that have a name, in the order of the simulation. */
    public static List<String> codes() {
        return CODES;
    }
}
